const transitions = ($.steps.getTransitions.response || {}).transitions || [];
const target = $.input.targetStatus.toLowerCase();

const match = transitions.find(t => t.name.toLowerCase() === target || (t.to && t.to.name && t.to.name.toLowerCase() === target));

if (!match) {
  const available = transitions.map(t => `${t.name} (id: ${t.id}, to: ${t.to ? t.to.name : 'unknown'})`).join(', ');
  throw new Error(`No transition found for target status "${$.input.targetStatus}". Available transitions: ${available || 'none'}`);
}

// Build transition payload
const payload = { transition: { id: match.id } };

if ($.input.comment) {
  payload.update = {
    comment: [{
      add: {
        body: {
          type: 'doc',
          version: 1,
          content: [{
            type: 'paragraph',
            content: [{ type: 'text', text: $.input.comment }]
          }]
        }
      }
    }]
  };
}

if ($.input.resolution) {
  payload.fields = payload.fields || {};
  payload.fields.resolution = { name: $.input.resolution };
}

return { payload, transitionId: match.id, transitionName: match.name, targetStatusName: match.to ? match.to.name : match.name };

const transitionName = $.steps.findTransition.output.transitionName;
const targetStatus = $.steps.findTransition.output.targetStatusName;
const issueKey = $.input.issueIdOrKey;

return {
  issueKey,
  transitionId: $.steps.findTransition.output.transitionId,
  transitionName,
  newStatus: targetStatus,
  hadComment: !!$.input.comment,
  hadResolution: !!$.input.resolution,
  success: true,
  summary: `Transitioned ${issueKey} via "${transitionName}" to "${targetStatus}"${$.input.comment ? ' with comment' : ''}${$.input.resolution ? ' (resolution: ' + $.input.resolution + ')' : ''}`
};
